import { FPSCounter } from './FPSCounter';
import { ImportedMeshAxesGizmo } from './ImportedMeshAxesGizmo';
import { DebugPanel } from './DebugPanel';
import { getShaderById, type ShaderDefinition } from '../shaders/shaderRegistry';
import { useSocketSync, type VolumetricState } from '../hooks/useSocketSync';
import { useUrlLaunch } from '../hooks/useUrlLaunch';
import { isCompositePreset, type ShaderPreset } from '../utils/types/presets';
import { getPerformancePreset, type PerformanceSettings } from '../types/performanceSettings';
import { getDefaultVolumetricState, buildGlobalSettings } from '../utils/stateGenerator';
import { resolveModelUrl } from '../utils/voxelUtils';
import { getCategoryDefaultValues } from '../utils/levaHelpers';
import { getSocketSessionId } from '../utils/sessionUtils';
import { CONFIG } from '../config/environment';
import { computeActiveLayerPresetsFromSequence, getActiveTagLabelFromSequence, getSequenceDurationMs, getTagSegments } from '../core/sequencer';
import type { TimelineSequence } from '../utils/types/presets';
import { getPreviewScaleFactors } from '../utils/outputScaling';
import {
    buildVolumetricCameraBounds,
    deriveCameraStateFromWorldPosition,
    getDefaultCameraState,
    getWorldCameraPosition,
    sanitizeCameraRotation,
    sanitizeCameraTarget,
    sanitizeCameraZoom,
    syncPerspectiveCamera,
} from '../utils/volumetricCamera';

const CAMERA_EPSILON = 1e-3;

function UrlLaunchSocketAgent({ onPhaseChange }: { onPhaseChange?: (phase: 'idle' | 'loading' | 'ready' | 'not_found' | 'error') => void }) {
    const { socket, remoteState, isMasterClient, claimMaster, broadcastUpdate } = useSocketSync(true, 'volumetric_output_fs', true);
    useUrlLaunch({ socket, remoteState, isMasterClient, claimMaster, broadcastUpdate, onPhaseChange: (d) => onPhaseChange?.(d.phase) });
    return null;
}

export function VolumetricOutputFullscreen() {
    const { remoteState, isMasterClient, isConnected, socket, broadcastUpdate } = useSocketSync(false, 'volumetric_output_fs');
    const orbitControlsRef = useRef<any>(null);

    // --- Local state for VIZ controls ---
    const defaults = useMemo(() => getDefaultVolumetricState(), []);

    // Camera
    const [cameraPosition, setCameraPosition] = useState({ x: 70, y: -40, z: 70 });
    const [cameraTarget, setCameraTarget] = useState({ x: 0, y: 0, z: 0 });
    const [cameraZoom, setCameraZoom] = useState(100);
    const [viewportAspect, setViewportAspect] = useState(() => (
        typeof window === 'undefined' ? 16 / 9 : window.innerWidth / Math.max(window.innerHeight, 1)
    ));

    // Performance
    const [performanceSettings, setPerformanceSettings] = useState<PerformanceSettings>(getPerformancePreset('high'));

    // Auto-rotation
    const [autoRotateYaw, setAutoRotateYaw] = useState(0);
    const [autoRotatePitch, setAutoRotatePitch] = useState(0);

    // View mode
    const [viewMode, setViewMode] = useState<'voxel' | 'volume'>('voxel');

    // Visualization params (from category defaults)
    const [visualizationParams, setVisualization] = useState<Record<string, any>>(() => ({
        ...getCategoryDefaultValues('visualization'),
        clipSizeX: 64, clipSizeY: 64, clipSizeZ: 64
    }));

    // Volume params
    const [volumeParams, setVolume] = useState<Record<string, any>>(() => getCategoryDefaultValues('volume'));

    // Imported textures
    const [importedTextures, setImportedTextures] = useState<Map<string, THREE.Texture>>(new Map());
    const [computeTexture, setComputeTexture] = useState<THREE.Texture | null>(null);

    // Buffer stats
    const [bufferStats, setBufferStats] = useState<{ count: number; details: Array<{ layerId: string; shaderId: string; presetName: string }> }>({
        count: 0, details: []
    });

    // --- Auto-rotation animation ---
    useEffect(() => {
        const handleResize = () => {
            setViewportAspect(window.innerWidth / Math.max(window.innerHeight, 1));
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        if (autoRotateYaw === 0 && autoRotatePitch === 0) return;
        const DEG = Math.PI / 180;
        const RAD = 180 / Math.PI;
        let lastTime = performance.now();
        let animId: number;

        const animate = () => {
            const now = performance.now();
            const dt = (now - lastTime) / 1000;
            lastTime = now;

            if (orbitControlsRef.current?.object) {
                const controls = orbitControlsRef.current;
                const target = controls.target ?? new THREE.Vector3(cameraTarget.x, cameraTarget.y, cameraTarget.z);
                const pos = controls.object.position;
                const x = pos.x - target.x;
                const y = pos.y - target.y;
                const z = pos.z - target.z;
                const distance = Math.sqrt(x * x + y * y + z * z);
                const currentPitch = Math.asin(y / (distance || 1)) * RAD;
                const currentYaw = Math.atan2(x, z) * RAD;

                const newYaw = currentYaw + autoRotateYaw * dt;
                const newPitch = Math.max(-89, Math.min(89, currentPitch + autoRotatePitch * dt));

                const yawRad = newYaw * DEG;
                const pitchRad = newPitch * DEG;
                const nx = distance * Math.cos(pitchRad) * Math.sin(yawRad);
                const ny = distance * Math.sin(pitchRad);
                const nz = distance * Math.cos(pitchRad) * Math.cos(yawRad);

                controls.object.position.set(target.x + nx, target.y + ny, target.z + nz);
                controls.object.lookAt(target.x, target.y, target.z);
                controls.update();
            }

            animId = requestAnimationFrame(animate);
        };

        animId = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(animId);
    }, [autoRotateYaw, autoRotatePitch, cameraTarget]);

    // --- Load camera config ---
    useEffect(() => {
        fetch('/volumetric/api/camera-config')
            .then(res => res.json())
            .then(data => {
                const rotation = data.rotation || { x: 70, y: -40, z: 70 };
                const target = sanitizeCameraTarget(data.target);
                const zoom = data.zoom || 100;
                const perfSettings = data.performanceSettings || getPerformancePreset(data.renderQuality || 'high');
                setPerformanceSettings(perfSettings);
                setCameraPosition(rotation);
                setCameraTarget(target);
                setCameraZoom(zoom);
            })
            .catch(() => {});
    }, []);

    // --- Sync performance from remoteState ---
    useEffect(() => {
        if (remoteState?.performanceSettings) setPerformanceSettings(remoteState.performanceSettings);
        if (remoteState?.vizPerformanceSettings) setPerformanceSettings(remoteState.vizPerformanceSettings);
    }, [remoteState?.performanceSettings, remoteState?.vizPerformanceSettings]);

    // --- Derive render mode ---
    const isPerformanceMode = remoteState?.activeLayerPresets !== undefined && remoteState?.renderMode === 'performance';
    const activeShader = useMemo(() => {
        if (!remoteState || isPerformanceMode) return undefined;
        if (remoteState.shaderId) return getShaderById(remoteState.shaderId);
        return undefined;
    }, [remoteState?.shaderId, isPerformanceMode, remoteState?.params]);

    const activeLayerPresets = useMemo(() => {
        if (!remoteState || !isPerformanceMode) return undefined;
        return remoteState.activeLayerPresets;
    }, [remoteState?.activeLayerPresets, isPerformanceMode]);

    // Resolution
    const resolutionX = remoteState?.outputPreset?.resolutionX || 64;
    const resolutionY = remoteState?.outputPreset?.resolutionY || 64;
    const resolutionZ = remoteState?.outputPreset?.resolutionZ || 64;
    const previewScale = useMemo(() => getPreviewScaleFactors(remoteState?.outputPreset), [remoteState?.outputPreset]);

    // Visualization & params from state
    const visualization = remoteState?.visualization || defaults.visualization;
    const params = remoteState?.params || {};
    const audio = remoteState?.audio || defaults.audio;
    const cameraBounds = useMemo(() => buildVolumetricCameraBounds({
        resolutionX,
        resolutionY,
        resolutionZ,
        previewScaleX: previewScale.x,
        previewScaleY: previewScale.y,
        previewScaleZ: previewScale.z,
        clipSizeX: visualization.clipSizeX ?? visualizationParams.clipSizeX,
        clipSizeY: visualization.clipSizeY ?? visualizationParams.clipSizeY,
        clipSizeZ: visualization.clipSizeZ ?? visualizationParams.clipSizeZ,
        clipStretch: visualization.clipStretch ?? visualizationParams.clipStretch,
        aspect: viewportAspect,
        fov: 45,
    }), [
        resolutionX,
        resolutionY,
        resolutionZ,
        previewScale.x,
        previewScale.y,
        previewScale.z,
        visualization.clipSizeX,
        visualization.clipSizeY,
        visualization.clipSizeZ,
        visualization.clipStretch,
        visualizationParams.clipSizeX,
        visualizationParams.clipSizeY,
        visualizationParams.clipSizeZ,
        visualizationParams.clipStretch,
        viewportAspect,
    ]);

    // --- Sequencer Override & Tags ---
    const sequencerOverride = remoteState?.sequencerOverride;
    const overrideEnabled = !!sequencerOverride?.enabled && !!sequencerOverride?.loop && !!sequencerOverride?.sequence && !!sequencerOverride?.baseState;
    const overrideSequence = sequencerOverride?.sequence as TimelineSequence | undefined;
    const overrideDurationMs = useMemo(() => overrideSequence ? getSequenceDurationMs(overrideSequence) : 0, [overrideSequence]);
    const overrideIsPlaying = overrideEnabled ? (sequencerOverride?.isPlaying !== false) : false;
    const overrideRemotePlayheadMs = typeof sequencerOverride?.playheadMs === 'number' && isFinite(sequencerOverride.playheadMs) ? Math.max(0, sequencerOverride.playheadMs) : 0;

    const [overridePlayheadMs, setOverridePlayheadMs] = useState(0);

    useEffect(() => {
        if (!overrideEnabled || !overrideSequence) return;
        const duration = Math.max(1, overrideDurationMs || 1);
        if (!overrideIsPlaying) {
            setOverridePlayheadMs(Math.max(0, Math.min(duration, overrideRemotePlayheadMs)));
            return;
        }
        const startedAt = typeof sequencerOverride?.startedAt === 'number' ? sequencerOverride.startedAt : Date.now();
        let raf = 0;

        const tick = () => {
            const now = Date.now();
            const raw = now - startedAt;
            const t = ((raw % duration) + duration) % duration;
            setOverridePlayheadMs(t);
            raf = requestAnimationFrame(tick);
        };

        raf = requestAnimationFrame(tick);
        return () => cancelAnimationFrame(raf);
    }, [overrideEnabled, overrideSequence, overrideDurationMs, overrideIsPlaying, overrideRemotePlayheadMs, sequencerOverride?.startedAt]);

    const tagOverlayEnabled = (remoteState as any)?.sequencerTags?.enabled ?? (sequencerOverride as any)?.baseState?.sequencerTags?.enabled ?? false;
    const tagOverlayLabel = useMemo(() => {
        if (!tagOverlayEnabled) return '';
        if (overrideEnabled && overrideSequence) return getActiveTagLabelFromSequence(overrideSequence, overridePlayheadMs);
        return (remoteState as any)?.sequencerTags?.activeLabel || '';
    }, [tagOverlayEnabled, overrideEnabled, overrideSequence, overridePlayheadMs, remoteState]);

    const overlaySegments = useMemo(() => {
        if (!overrideEnabled || !overrideSequence) return [];
        return getTagSegments(overrideSequence);
    }, [overrideEnabled, overrideSequence]);

    const activeOverlaySegment = useMemo(() => {
        if (!overlaySegments.length) return null;
        let active = overlaySegments[0];
        for (const seg of overlaySegments) {
            if (overridePlayheadMs >= seg.startMs && overridePlayheadMs < seg.endMs) { active = seg; break; }
            if (seg.startMs <= overridePlayheadMs) active = seg;
        }
        return active;
    }, [overlaySegments, overridePlayheadMs]);

    const sendSequencerCommand = useCallback((command: string, payload?: any) => {
        if (!socket) return;
        socket.emit('sequencer:command', { sessionId: getSocketSessionId(), command, payload: payload ?? null });
    }, [socket]);

    const seekThrottleRef = useRef<{ raf: number | null; tMs: number }>({ raf: null, tMs: 0 });
    const requestSeek = useCallback((tMs: number) => {
        setOverridePlayheadMs(tMs);
        seekThrottleRef.current.tMs = tMs;
        if (seekThrottleRef.current.raf != null) return;
        seekThrottleRef.current.raf = window.requestAnimationFrame(() => {
            seekThrottleRef.current.raf = null;
            sendSequencerCommand('seek', { tMs: seekThrottleRef.current.tMs });
        });
    }, [sendSequencerCommand]);

    const prevCameraPositionRef = useRef(cameraPosition);
    const prevCameraTargetRef = useRef(cameraTarget);
    const prevCameraZoomRef = useRef(cameraZoom);
    const isApplyingCameraStateRef = useRef(false);
    const isUserInteractingWithCameraRef = useRef(false);

    useEffect(() => {
        setCameraPosition(prev => {
            const next = sanitizeCameraRotation(prev, cameraBounds.fitDistance);
            const changed =
                Math.abs(next.x - prev.x) > CAMERA_EPSILON ||
                Math.abs(next.y - prev.y) > CAMERA_EPSILON ||
                Math.abs(next.z - prev.z) > CAMERA_EPSILON;
            if (changed) prevCameraPositionRef.current = next;
            return changed ? next : prev;
        });
        setCameraZoom(prev => {
            const next = sanitizeCameraZoom(prev, cameraBounds);
            const changed = Math.abs(next - prev) > CAMERA_EPSILON;
            if (changed) prevCameraZoomRef.current = next;
            return changed ? next : prev;
        });
    }, [cameraBounds]);

    useEffect(() => {
        const controls = orbitControlsRef.current;
        if (!controls?.object || isUserInteractingWithCameraRef.current) return;

        const nextPosition = getWorldCameraPosition(cameraPosition, cameraZoom, cameraBounds);
        const nextTarget = sanitizeCameraTarget(cameraTarget);
        const camera = controls.object;
        isApplyingCameraStateRef.current = true;
        controls.minDistance = cameraBounds.minDistance;
        controls.maxDistance = cameraBounds.maxDistance;
        syncPerspectiveCamera(camera, cameraBounds);
        controls.target.set(nextTarget.x, nextTarget.y, nextTarget.z);
        camera.position.set(nextTarget.x + nextPosition.x, nextTarget.y + nextPosition.y, nextTarget.z + nextPosition.z);
        camera.lookAt(nextTarget.x, nextTarget.y, nextTarget.z);
        controls.update();
        prevCameraPositionRef.current = sanitizeCameraRotation(cameraPosition, cameraBounds.fitDistance);
        prevCameraTargetRef.current = nextTarget;
        prevCameraZoomRef.current = sanitizeCameraZoom(cameraZoom, cameraBounds);

        const rafId = requestAnimationFrame(() => {
            isApplyingCameraStateRef.current = false;
        });

        return () => cancelAnimationFrame(rafId);
    }, [cameraPosition, cameraTarget, cameraZoom, cameraBounds]);

    useEffect(() => {
        const controls = orbitControlsRef.current;
        if (!controls) return;

        let rafId: number | null = null;

        const syncFromControls = () => {
            const activeControls = orbitControlsRef.current;
            if (!activeControls?.object || isApplyingCameraStateRef.current) return;
            const nextTarget = sanitizeCameraTarget(activeControls.target);
            const nextState = deriveCameraStateFromWorldPosition({
                x: activeControls.object.position.x - nextTarget.x,
                y: activeControls.object.position.y - nextTarget.y,
                z: activeControls.object.position.z - nextTarget.z,
            }, cameraBounds);
            const positionChanged =
                Math.abs(nextState.position.x - prevCameraPositionRef.current.x) > CAMERA_EPSILON ||
                Math.abs(nextState.position.y - prevCameraPositionRef.current.y) > CAMERA_EPSILON ||
                Math.abs(nextState.position.z - prevCameraPositionRef.current.z) > CAMERA_EPSILON;
            const targetChanged =
                Math.abs(nextTarget.x - prevCameraTargetRef.current.x) > CAMERA_EPSILON ||
                Math.abs(nextTarget.y - prevCameraTargetRef.current.y) > CAMERA_EPSILON ||
                Math.abs(nextTarget.z - prevCameraTargetRef.current.z) > CAMERA_EPSILON;
            const zoomChanged = Math.abs(nextState.zoom - prevCameraZoomRef.current) > 0.25;
            if (!positionChanged && !targetChanged && !zoomChanged) return;

            prevCameraPositionRef.current = nextState.position;
            prevCameraTargetRef.current = nextTarget;
            prevCameraZoomRef.current = nextState.zoom;
            setCameraPosition(nextState.position);
            setCameraTarget(nextTarget);
            setCameraZoom(nextState.zoom);
        };

        const handleControlsStart = () => {
            isUserInteractingWithCameraRef.current = true;
        };

        const handleControlsEnd = () => {
            isUserInteractingWithCameraRef.current = false;
            syncFromControls();
        };

        const handleControlsChange = () => {
            if (rafId !== null) return;
            rafId = requestAnimationFrame(() => {
                rafId = null;
                syncFromControls();
            });
        };

        controls.addEventListener('start', handleControlsStart);
        controls.addEventListener('end', handleControlsEnd);
        controls.addEventListener('change', handleControlsChange);

        return () => {
            if (rafId !== null) cancelAnimationFrame(rafId);
            controls.removeEventListener('start', handleControlsStart);
            controls.removeEventListener('end', handleControlsEnd);
            controls.removeEventListener('change', handleControlsChange);
        };
    }, [cameraBounds]);

    return (
        <div style={{ width: '100vw', height: '100vh', background: '#000', position: 'relative', overflow: 'hidden' }}>
            <UrlLaunchSocketAgent />

            {!remoteState ? (
                <div style={{
                    width: '100%', height: '100%', display: 'flex',
                    alignItems: 'center', justifyContent: 'center', color: '#666',
                    fontFamily: 'monospace', fontSize: 18, letterSpacing: '0.05em'
                }}>
                    {isConnected ? 'LOADING...' : 'CONNECTING...'}
                </div>
            ) : (
                <>
                    {/* Mode Indicator */}
                    <ModeIndicator mode={remoteState?.renderMode === 'performance' ? 'performance' : 'effect-edition'} position="top-left" />

                    {/* Master/Slave */}
                    <div style={{ position: 'fixed', top: '20px', left: '80px', zIndex: 9999 }}>
                        <MasterStatusIndicator isMaster={isMasterClient} />
                    </div>

                    {/* Tags Overlay */}
                    {(tagOverlayLabel || '').trim() ? (
                        <div style={{
                            position: 'fixed', left: '50%', bottom: '14px',
                            transform: 'translateX(-50%)', zIndex: 10010,
                            padding: '12px 14px', borderRadius: '14px',
                            background: 'rgba(0, 0, 0, 0.78)',
                            border: '1px solid rgba(255, 200, 0, 0.35)',
                            color: 'rgba(255, 235, 190, 0.98)',
                            fontFamily: 'monospace', letterSpacing: '0.04em',
                            maxWidth: '92vw', minWidth: 'min(640px, 92vw)'
                        }}>
                            <div style={{
                                fontSize: '22px', textAlign: 'center',
                                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap'
                            }}>
                                {tagOverlayLabel}
                            </div>
                            {overrideEnabled && overrideSequence && activeOverlaySegment && (
                                <>
                                    <div style={{ height: 6, borderRadius: 999, background: 'rgba(255,255,255,0.12)', overflow: 'hidden', marginTop: 10 }}>
                                        <div style={{
                                            height: '100%',
                                            width: `${Math.max(0, Math.min(1, (overridePlayheadMs - activeOverlaySegment.startMs) / Math.max(1, activeOverlaySegment.endMs - activeOverlaySegment.startMs))) * 100}%`,
                                            background: 'rgba(255, 200, 0, 0.85)'
                                        }} />
                                    </div>
                                    <div style={{ display: 'flex', gap: 10, alignItems: 'center', marginTop: 10 }}>
                                        <button onClick={() => sendSequencerCommand('prev_tag')}
                                            style={{ width: 42, height: 34, borderRadius: 10, background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.12)', color: '#fff', cursor: 'pointer' }} type="button">◀</button>
                                        <button onClick={() => sendSequencerCommand('toggle_play')}
                                            style={{ width: 56, height: 34, borderRadius: 10, background: 'rgba(255,200,0,0.18)', border: '1px solid rgba(255,200,0,0.35)', color: '#fff', cursor: 'pointer' }} type="button">
                                            {overrideIsPlaying ? '⏸' : '▶'}
                                        </button>
                                        <button onClick={() => sendSequencerCommand('next_tag')}
                                            style={{ width: 42, height: 34, borderRadius: 10, background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.12)', color: '#fff', cursor: 'pointer' }} type="button">▶</button>
                                        <SeekBar
                                            currentMs={overridePlayheadMs}
                                            durationMs={overrideDurationMs}
                                            onSeek={requestSeek}
                                            style={{ flex: 1, height: 34 }}
                                        />
                                    </div>
                                </>
                            )}
                        </div>
                    ) : null}

                    {/* VIZ Controls Sidebar */}
                    <div style={{
                        position: 'fixed', top: '10px', right: '10px', zIndex: 10001,
                        maxHeight: 'calc(100vh - 20px)', overflowY: 'auto',
                        width: 'min(320px, 40vw)'
                    }}>
                        <ControlsSidebar3
                            embedded={true}
                            showVolumetricCube={true}
                            onShowVolumetricCubeChange={() => {}}
                            onResetView={() => {
                                const nextCamera = getDefaultCameraState(cameraBounds);
                                setAutoRotateYaw(0);
                                setAutoRotatePitch(0);
                                setCameraPosition(nextCamera.position);
                                setCameraTarget({ x: 0, y: 0, z: 0 });
                                setCameraZoom(nextCamera.zoom);
                            }}
                            visualizationParams={visualizationParams}
                            onVisualizationChange={(key, value) => {
                                setVisualization(prev => ({ ...prev, [key]: value }));
                            }}
                            onVisualizationReset={() => {
                                const vizDefaults = getCategoryDefaultValues('visualization');
                                setVisualization({
                                    ...vizDefaults,
                                    clipSizeX: resolutionX, clipSizeY: resolutionY, clipSizeZ: resolutionZ,
                                });
                            }}
                            cameraPosition={cameraPosition}
                            cameraZoom={cameraZoom}
                            cameraZoomMin={cameraBounds.minZoom}
                            cameraZoomMax={cameraBounds.maxZoom}
                            onCameraRotationChange={(rotation) => {
                                setCameraPosition(sanitizeCameraRotation(rotation, cameraBounds.fitDistance));
                            }}
                            onCameraZoomChange={(zoom) => {
                                setCameraZoom(sanitizeCameraZoom(zoom, cameraBounds));
                            }}
                            performanceSettings={performanceSettings}
                            onPerformanceSettingsChange={setPerformanceSettings}
                            onCameraSave={async () => {
                                try {
                                    await fetch('/volumetric/api/camera-config', {
                                        method: 'POST',
                                        headers: { 'Content-Type': 'application/json' },
                                        body: JSON.stringify({
                                            rotation: cameraPosition,
                                            target: cameraTarget,
                                            zoom: cameraZoom,
                                            renderQuality: 'high',
                                            performanceSettings
                                        })
                                    });
                                } catch {}
                            }}
                            onCameraResetSaved={() => {
                                fetch('/volumetric/api/camera-config')
                                    .then(res => res.json())
                                    .then(data => {
                                        const rotation = data.rotation || { x: 70, y: -40, z: 70 };
                                        const target = sanitizeCameraTarget(data.target);
                                        const zoom = data.zoom || 100;
                                        const perfSettings = data.performanceSettings || getPerformancePreset(data.renderQuality || 'high');
                                        setPerformanceSettings(perfSettings);
                                        setCameraPosition(rotation);
                                        setCameraTarget(target);
                                        setCameraZoom(zoom);
                                    })
                                    .catch(() => {});
                            }}
                            onCameraResetStandard={() => {
                                const standardSettings = getPerformancePreset('high');
                                const nextCamera = getDefaultCameraState(cameraBounds);
                                setPerformanceSettings(standardSettings);
                                setAutoRotateYaw(0);
                                setAutoRotatePitch(0);
                                setCameraPosition(nextCamera.position);
                                setCameraTarget({ x: 0, y: 0, z: 0 });
                                setCameraZoom(nextCamera.zoom);
                            }}
                            autoRotateYaw={autoRotateYaw}
                            autoRotatePitch={autoRotatePitch}
                            onAutoRotateYawChange={setAutoRotateYaw}
                            onAutoRotatePitchChange={setAutoRotatePitch}
                            viewMode={viewMode}
                            onViewModeChange={setViewMode}
                            volumeParams={volumeParams}
                            onVolumeChange={(key, value) => setVolume(prev => ({ ...prev, [key]: value }))}
                            onVolumeReset={() => setVolume(getCategoryDefaultValues('volume'))}
                        />
                    </div>

                    {/* 3D Canvas */}
                    <Canvas
                        camera={{
                            position: (() => {
                                const pos = getWorldCameraPosition(cameraPosition, cameraZoom, cameraBounds);
                                return [
                                    cameraTarget.x + pos.x,
                                    cameraTarget.y + pos.y,
                                    cameraTarget.z + pos.z,
                                ] as [number, number, number];
                            })(),
                            fov: 45,
                            near: cameraBounds.near,
                            far: cameraBounds.far,
                        }}
                        gl={{ preserveDrawingBuffer: true, antialias: true }}
                        dpr={1}
                        style={{ width: '100%', height: '100%', position: 'absolute', top: 0, left: 0 }}
                    >
                        {/* Mesh Voxelizers */}
                        {activeLayerPresets !== undefined ? (
                            <VolumetricVoxelizers
                                presets={(activeLayerPresets || [])
                                    .flatMap(preset => isCompositePreset(preset) ? (preset as any).layers : [preset])
                                    .filter(p => p && (p as any).shaderId === 'imported_mesh') as ShaderPreset[]}
                                outputResolution={{ x: resolutionX, y: resolutionY, z: resolutionZ }}
                                onImportedTextureUpdate={(key, texture) => {
                                    setImportedTextures(prev => {
                                        if (prev.get(key) === texture) return prev;
                                        const next = new Map(prev);
                                        next.set(key, texture);
                                        return next;
                                    });
                                }}
                            />
                        ) : (
                            activeShader?.id === 'imported_mesh' && (
                                <MeshVoxelizer
                                    modelUrl={resolveModelUrl(params.uModelUrl) || null}
                                    fileType={params.uModelExt || 'gltf'}
                                    fileMap={undefined}
                                    resolutionX={resolutionX}
                                    resolutionY={resolutionY}
                                    resolutionZ={resolutionZ}
                                    speedX={visualization.speedX ?? 0}
                                    speedY={visualization.speedY ?? 0}
                                    speedZ={visualization.speedZ ?? 0}
                                    speedRotationX={visualization.speedRotationX ?? 0}
                                    speedRotationY={visualization.speedRotationY ?? 0}
                                    speedRotationZ={visualization.speedRotationZ ?? 0}
                                    animScrub={params.uAnimScrub ?? false}
                                    animTime={params.uAnimTime ?? 0}
                                    repeatX={params.uRepeatX ?? 1}
                                    repeatY={params.uRepeatY ?? 1}
                                    repeatZ={params.uRepeatZ ?? 1}
                                    sepX={params.uSepX ?? 0}
                                    sepY={params.uSepY ?? 0}
                                    sepZ={params.uSepZ ?? 0}
                                    transform={{
                                        position: [
                                            (params.uPosX || 0) + (visualization.offsetX || 0),
                                            (params.uPosY || 0) + (visualization.offsetY || 0),
                                            (params.uPosZ || 0) + (visualization.offsetZ || 0)
                                        ],
                                        rotation: [
                                            ((params.uRotX || 0) + (visualization.globalRotationX || 0)) * Math.PI / 180,
                                            ((params.uRotY || 0) + (visualization.globalRotationY || 0)) * Math.PI / 180,
                                            ((params.uRotZ || 0) + (visualization.globalRotationZ || 0)) * Math.PI / 180
                                        ],
                                        scale: (params.uModelScale || 1.0) * (visualization.scaleX || 1.0)
                                    }}
                                    transformAnimationSource={{
                                        uPos: [params.uPosX || 0, params.uPosY || 0, params.uPosZ || 0],
                                        uRot: [params.uRotX || 0, params.uRotY || 0, params.uRotZ || 0],
                                        uScale: params.uModelScale || 1.0,
                                        offset: [visualization.offsetX || 0, visualization.offsetY || 0, visualization.offsetZ || 0],
                                        globalRot: [visualization.globalRotationX || 0, visualization.globalRotationY || 0, visualization.globalRotationZ || 0],
                                        globalScale: visualization.scaleX || 1.0,
                                        axisMappingEnabled: Boolean(params.uRotateXZMapping90)
                                    }}
                                    animationStates={remoteState.animationStates}
                                    animationId="volumetric-output-fs"
                                    animSpeed={params.uAnimSpeed ?? 1}
                                    fillAmount={params.uFillAmount ?? 0}
                                    onVoxelTextureUpdate={(texture) => {
                                        setImportedTextures(prev => {
                                            if (prev.get('main') === texture) return prev;
                                            const next = new Map(prev);
                                            next.set('main', texture);
                                            return next;
                                        });
                                    }}
                                />
                            )
                        )}

                        {/* Text Renderers */}
                        {activeLayerPresets !== undefined ? (
                            <VolumetricVoxelizers
                                presets={(activeLayerPresets || [])
                                    .flatMap(preset => isCompositePreset(preset) ? (preset as any).layers : [preset])
                                    .filter(p => p && (p as any).shaderId === 'text_3d') as ShaderPreset[]}
                                outputResolution={{ x: resolutionX, y: resolutionY, z: resolutionZ }}
                                onImportedTextureUpdate={(key, texture) => {
                                    setImportedTextures(prev => {
                                        if (prev.get(key) === texture) return prev;
                                        const next = new Map(prev);
                                        next.set(key, texture);
                                        return next;
                                    });
                                }}
                            />
                        ) : (
                            activeShader?.id === 'text_3d' && (
                                <TextRendererUltimateWrapper
                                    text={params.uTextContent || 'HELLO'}
                                    font={params.uTextFont || 'SQUARE'}
                                    lineWidth={params.uLineWidth || 0.03}
                                    size={params.uTextSize || 2.0}
                                    letterSpacing={params.uLetterSpacing || 0.2}
                                    boundsLimit={params.uBoundsLimit || 1.0}
                                    rotateLetterX={params.uRotateLetterX || 0}
                                    rotateLetterY={params.uRotateLetterY || 0}
                                    rotateLetterZ={params.uRotateLetterZ || 0}
                                    scaleX={visualization.scaleX ?? 1.0}
                                    scaleY={visualization.scaleY ?? 1.0}
                                    scaleZ={visualization.scaleZ ?? 1.0}
                                    offsetX={visualization.offsetX || 0}
                                    offsetY={visualization.offsetY || 0}
                                    offsetZ={visualization.offsetZ || 0}
                                    rotationX={visualization.globalRotationX || 0}
                                    rotationY={visualization.globalRotationY || 0}
                                    rotationZ={visualization.globalRotationZ || 0}
                                    speedX={(visualization.speedX ?? 0) * 0.1}
                                    speedY={(visualization.speedY ?? 0) * 0.1}
                                    speedZ={(visualization.speedZ ?? 0) * 0.1}
                                    onVoxelTextureUpdate={(texture) => {
                                        setImportedTextures(prev => {
                                            const newMap = new Map(prev);
                                            newMap.set('main', texture);
                                            return newMap;
                                        });
                                    }}
                                />
                            )
                        )}

                        <color attach="background" args={['#000']} />
                        <OrbitControls
                            ref={orbitControlsRef}
                            makeDefault
                            enableDamping
                            dampingFactor={0.05}
                            minDistance={cameraBounds.minDistance}
                            maxDistance={cameraBounds.maxDistance}
                        />

                        <ImportedMeshAxesGizmo
                            params={activeShader?.id === 'imported_mesh' ? params : undefined}
                            globalSettings={visualization}
                            resolutionX={resolutionX}
                            resolutionY={resolutionY}
                            resolutionZ={resolutionZ}
                            speedRotationX={visualization.speedRotationX ?? 0}
                            speedRotationY={visualization.speedRotationY ?? 0}
                            speedRotationZ={visualization.speedRotationZ ?? 0}
                        />

                        <FPSCounter onFPSUpdate={() => {}} />

                        <VolumetricCube
                            performanceSettings={performanceSettings}
                            resolutionX={resolutionX}
                            resolutionY={resolutionY}
                            resolutionZ={resolutionZ}
                            previewScaleX={previewScale.x}
                            previewScaleY={previewScale.y}
                            previewScaleZ={previewScale.z}
                            voxelScale={visualization.voxelScale ?? defaults.visualization.voxelScale}
                            clipSizeX={visualization.clipSizeX ?? defaults.visualization.clipSizeX}
                            clipSizeY={visualization.clipSizeY ?? defaults.visualization.clipSizeY}
                            clipSizeZ={visualization.clipSizeZ ?? defaults.visualization.clipSizeZ}
                            clipStretch={visualization.clipStretch ?? defaults.visualization.clipStretch}
                            scaleX={visualization.scaleX ?? defaults.visualization.scaleX}
                            scaleY={visualization.scaleY ?? defaults.visualization.scaleY}
                            scaleZ={visualization.scaleZ ?? defaults.visualization.scaleZ}
                            offsetX={visualization.offsetX ?? defaults.visualization.offsetX}
                            offsetY={visualization.offsetY ?? defaults.visualization.offsetY}
                            offsetZ={visualization.offsetZ ?? defaults.visualization.offsetZ}
                            speedX={visualization.speedX ?? defaults.visualization.speedX}
                            speedY={visualization.speedY ?? defaults.visualization.speedY}
